const MODEL_DEFINICIONES = [{"n":"Nº 1","definicion":"El contrato como parámetro","responsable":"Comercial","bloquea":"M-16","queDefinir":"Ritmo, tolerancia, merma, volumen comprometido, tope de cupos y espacio de cada contrato vigente. Sin estos valores el contrato no pasa a vigente. v2: agrega la antelación del aviso (SLA 15–30 días), el alcance por defecto y la condición aduanera prevista."},{"n":"Nº 2","definicion":"Capacidad de cada balanza","responsable":"Tráfico · Balanza","bloquea":"M-26 · M-20 (tolerancia 4 %)","queDefinir":"Medir tn/h, camiones/h y disponibilidad por banda de B1, B2, B3 (zona de puerto), balanza de depósito y fiscal de puerto, y declarar cuál prevalece en la conciliación. v2: fijar la cola máxima que dispara la derivación por congestión."},{"n":"Nº 3","definicion":"Inventario de ubicaciones","responsable":"Depósito","bloquea":"M-10 · M-10a","queDefinir":"Relevamiento físico de depósitos, celdas, boxes y tanques con capacidad y método de recepción. Sin ubicación no hay trazabilidad por lote. v2: incluir fosa y noria, producto asignado y ocupación inicial por box."},{"n":"Nº 4","definicion":"Catálogo de causas de demora","responsable":"Operaciones · Calidad","bloquea":"M-29","queDefinir":"Lista cerrada con categoría, imputable y efecto sobre el ritmo contractual. v2: incorporar congestión de balanza, recepción lenta en depósito, desvío logístico (GPS) y avería / secuencia de bodegas del buque."},{"n":"Nº 5","definicion":"Plan de cuentas y objeto operativo","responsable":"Contabilidad","bloquea":"M-03 · M-03","queDefinir":"Plan de cuentas por sociedad con el objeto de costo de tipo operativo: la precondición de la registración automática y del margen por operativo."},{"n":"Nº 6","definicion":"Dotación de manos de referencia","responsable":"Operaciones Portuarias","bloquea":"M-07","queDefinir":"Manos de referencia por producto sólido a granel, para planificar antes de la confirmación del capitán."},{"n":"Nº 7","definicion":"Tabla de tolerancias operativas","responsable":"Operaciones · Logística · Tráfico","bloquea":"M-20","queDefinir":"Por cada proceso controlado: parámetro, valor base, tolerancia de exceso/defecto y acción al exceder (bloquear · autorización nominal · alertar y registrar). Hoy son criterio del coordinador de turno; pasan a ser dato con traza de quién autoriza cada desvío."},{"n":"Nº 8","definicion":"Especificaciones de calidad por producto","responsable":"Calidad","bloquea":"M-23","queDefinir":"Por cada producto con muestreo: parámetros, valor nominal, banda de tolerancia, método de ensayo, frecuencia, punto de control y acción fuera de especificación (bloquear despacho · segregar · degradar)."},{"n":"Nº 9","definicion":"Régimen regulatorio y habilitaciones","responsable":"Depósito · Calidad · Operaciones Portuarias","bloquea":"M-07 · M-10 · M-21 · M-21","queDefinir":"Por cada producto: si está alcanzado por RENPRE / RENAR. Por cada depósito: habilitaciones fiscal (incl. provisorio de Comirsa) y regulatorias con vencimiento y consecuencia. Catálogo de organismos externos y de documentos del expediente del buque con quién los emite y si bloquean el avance. Hoy la verificación es manual y no deja registro."},{"n":"Nº 10","definicion":"Fuentes y homologación del LineUp","responsable":"Operaciones Portuarias · Comercial","bloquea":"M-17 · M-09 · M-08 · M-21","queDefinir":"Qué LineUps se importan y con qué frecuencia (agencias, CGPSN, terminales de terceros), qué puertos y categorías de carga interesan (¿todo el río o solo fertilizantes y buques con potencial TyS?), quién es el curador que homologa buque / cliente / producto dentro de las 72 h, la tolerancia de variación de ETA que dispara alerta (M-20) y la regla de conflicto cuando dos fuentes informan tonelajes o fechas distintos (hoy: \"REVISAR\" en la columna de observaciones). Hoy la consolidación es manual (hoja \"Integrado\") y no queda trazada."},{"n":"Nº 11","definicion":"Catálogo de tipos de servicio (M-14)","responsable":"Comercial · Operaciones","bloquea":"M-14 · M-15 · M-16","queDefinir":"Lista de servicios simples (DESC, TRA, ALM…) y combinados, con componentes, origen (LineUp / solicitud), recursos que consume, controles obligatorios y etapas del Operativo que aplican. Sin esta lista no hay Operativo ni tarifa."},{"n":"Nº 12","definicion":"Criterio de destino y matriz de manos","responsable":"Planificación · Depósitos · Operaciones","bloquea":"M-07 · M-09 · M-10 · M-25","queDefinir":"Prioridad planta propia → satélite → alquilada; costo de flete y almacenaje de referencia por planta (M-09 ★); tn por mano y turno por producto (M-07 ★) y su variante por puerto / muelle / calidad."},{"n":"Nº 13","definicion":"Régimen de turnos de 6 h","responsable":"RRHH · Operaciones","bloquea":"M-33 · M-19 · M-16 (ritmo por turno)","queDefinir":"Cuatro turnos de 6 h y sus horarios (propuesta T1 06–12 · T2 12–18 · T3 18–24 · T4 00–06), inicio del día operativo, si el ritmo contractual (tn/turno) se redefine por turno de 6 h y el costo de habilitación de días inhábiles."},{"n":"Nº 14","definicion":"Catálogo de métodos seguros","responsable":"Seguridad e Higiene · cada sector dueño","bloquea":"M-34 · metodo_seguro de M-07 · M-10 · M-11 · M-12 · M-13 · M-14 · M-25 · M-26","queDefinir":"Inventario de procedimientos, instructivos, permisos, FDS, planes de emergencia y habilitaciones vigentes: tipo, documento, versión, responsable, vencimiento, días de aviso y acción al vencer (bloquear · alertar). Qué maestros exigen MS obligatorio."},{"n":"Nº 15","definicion":"Tramos de administración del programa","responsable":"Comercial · Planificación · Tráfico · Logística","bloquea":"M-17 · M-31 · M-32","queDefinir":"Qué atributos de LineUp, cupos y arribos escribe cada rol (tramo comercial / portuario / de portería / operativo) y quién corrige un dato del tramo ajeno (propuesta: Máster data / Administrador con motivo)."},{"n":"Nº 16","definicion":"Habilitación fiscal de balanzas y depósitos","responsable":"Tráfico · Depósito","bloquea":"M-26 (habilitada_fiscal) · M-10 (tipo fiscal · habilitación aduanera)","queDefinir":"Qué balanzas están habilitadas para pesar mercadería no nacionalizada y con qué vencimiento; qué depósitos son fiscales o fiscales temporarios. Es lo que filtra la planificación cuando Comercial declara \"no nacionalizada\"."},{"n":"Nº 17","definicion":"Operadores ferroviarios y playas de vías","responsable":"Logística · Comercial","bloquea":"M-32 · M-06 (rubro ferrocarril) · M-09 (playa de vías)","queDefinir":"Operadores (BCyL, NCA) como proveedores, playas de vías / desvíos por planta, ventanas típicas de descarga y carga de vagones, y si la descarga de vagones exige una tarea propia del plan."},{"n":"Nº 18","definicion":"Recursos por categoría: manos, puestos y choferes","responsable":"RRHH · Operaciones · Logística","bloquea":"M-13 (composicion_roles) · M-05 (puestos) · M-27","queDefinir":"Composición por roles de cada categoría de mano; dotación mínima y costo horario por puesto; universo de choferes habilitados (licencia, credencial, ART). Se planifica por cantidad, nunca por nombre."}];
